SELECT count(*), count(ref), sum(ref), total(ref), avg(ref), min(ref), max(ref), count(DISTINCT ref) FROM t1 WHERE iif(c1, 'a%b', 601) BETWEEN CAST(id AS INTEGER) AND nullif(c1, ref);
SELECT ref, count(*), group_concat(id, ';') FROM (SELECT * FROM t1 ORDER BY id) GROUP BY ref HAVING count(*) > 1 ORDER BY ref;
SELECT count(*), count(ref), sum(ref), total(ref), avg(ref), min(ref), max(ref), count(DISTINCT ref) FROM t1 WHERE id IS NULL;
SELECT ref, count(*), group_concat(id) FROM (SELECT * FROM t1 ORDER BY id) GROUP BY ref ORDER BY ref;
SELECT count(*), count(ref), sum(ref), total(ref), avg(ref), min(ref), max(ref), count(DISTINCT ref) FROM t1 WHERE nullif(CAST(2.5 AS NUMERIC), ref);
SELECT ref, count(*), group_concat(id, ';') FROM (SELECT * FROM t1 ORDER BY id) GROUP BY ref HAVING count(*) > 0 ORDER BY ref;
SELECT json_valid('{"name":"café","tags":["a","b"],"n":{"m":{"o":-1}}}'), json('{"name":"café","tags":["a","b"],"n":{"m":{"o":-1}}}'), json_type('{"name":"café","tags":["a","b"],"n":{"m":{"o":-1}}}'), json_array_length('{"name":"café","tags":["a","b"],"n":{"m":{"o":-1}}}'), json_extract('{"name":"café","tags":["a","b"],"n":{"m":{"o":-1}}}', '$.a', '$[1]', '$.b[2].c'), '{"name":"café","tags":["a","b"],"n":{"m":{"o":-1}}}' -> '$.b', '{"name":"café","tags":["a","b"],"n":{"m":{"o":-1}}}' ->> '$.n.m.o';
