SELECT json_set('{"name":"café","tags":["a","b"],"n":{"m":{"o":-1}}}', '$.z', 1), json_insert('{"name":"café","tags":["a","b"],"n":{"m":{"o":-1}}}', '$.a', 2), json_remove('{"name":"café","tags":["a","b"],"n":{"m":{"o":-1}}}', '$.a'), json_patch('{"a":1}', '{"b":2}');
SELECT json_group_array(id), json_group_object(CAST(id AS TEXT), id) FROM t0;
